   186→    }
   187→
   188→    [MethodImpl(MethodImplOptions.NoInlining)]
   189→    private static (uint baseLength, uint expLength, uint modulusLength) GetInputLengthsMayOverflow(ReadOnlySpan<byte> inputData)
   190→    {
