      "code_excerpt": "// PRIMARY: src/Nethermind/Nethermind.Core/ExecutionRequest/ExecutionRequestExtensions.cs:CalculateHashFromFlatEncodedRequests (lines 32-50)\npublic static Hash256 CalculateHashFromFlatEncodedRequests(byte[][]? flatEncodedRequests)\n{\n    using ArrayPoolList<byte> concatenatedHashes = new(Hash256.Size * MaxRequestsCount);\n    foreach (byte[] requests in flatEncodedRequests)\n    {\n        if (requests.Length <= 1) continue;  // skip empty request type sets\n        concatenatedHashes.AddRange(SHA256.HashData(requests));  // SHA256 of each type's flat encoding\n    }\n    // Two-level: SHA256(concat(SHA256(type0_requests), SHA256(type1_requests), SHA256(type2_requests)))\n    return new Hash256(SHA256.HashData(concatenatedHashes.UnsafeGetInternalArray().AsSpan(0, concatenatedHashes.Count)));\n}"
